package quicktype

import java.time.OffsetDateTime

import com.beust.klaxon.*

private fun <T> Klaxon.convert(k: kotlin.reflect.KClass<*>, fromJson: (JsonValue) -> T, toJson: (T) -> String, isUnion: Boolean = false) =
    this.converter(object: Converter {
        @Suppress("UNCHECKED_CAST")
        override fun toJson(value: Any)        = toJson(value as T)
        override fun fromJson(jv: JsonValue)   = fromJson(jv) as Any
        override fun canConvert(cls: Class<*>) = cls == k.java || (isUnion && cls.superclass == k.java)
    })

private val klaxon = Klaxon()
    .convert(OffsetDateTime::class, { OffsetDateTime.parse(it.string!!) }, { "\"${java.time.format.DateTimeFormatter.ISO_OFFSET_DATE_TIME.format(it)}\"" })
    .convert(Color::class,          { Color.fromValue(it.string!!) },      { Klaxon().toJsonString(it.value) })
    .convert(Either::class,         { Either.fromJson(it) },               { it.toJson() }, true)

class Ints(elements: Collection<Long>) : ArrayList<Long>(elements) {
    public fun toJson() = klaxon.toJsonString(this)

    companion object {
        public fun fromJson(json: String) = Ints(klaxon.parseArray<Any>(json)!!.map { when (it) { is Int -> it.toLong(); is Long -> it; else -> throw IllegalArgumentException() } })
    }
}
class Names(elements: Collection<String>) : ArrayList<String>(elements) {
    public fun toJson() = klaxon.toJsonString(this)

    companion object {
        public fun fromJson(json: String) = Names(klaxon.parseArray<String>(json)!!)
    }
}
class Table(elements: Map<String, Double>) : HashMap<String, Double>(elements) {
    public fun toJson() = klaxon.toJsonString(this)

    companion object {
        public fun fromJson(json: String) = Table (
            klaxon.parseJsonObject(java.io.StringReader(json)) as Map<String, Double>
        )
    }
}
class Bag(elements: Map<String, Map<String, Any?>>) : HashMap<String, Map<String, Any?>>(elements) {
    public fun toJson() = klaxon.toJsonString(this)

    companion object {
        public fun fromJson(json: String) = Bag (
            klaxon.parseJsonObject(java.io.StringReader(json)) as Map<String, Map<String, Any?>>
        )
    }
}
data class Count(val value: Long) {
    public fun toJson() = klaxon.toJsonString(value)

    companion object {
        public fun fromJson(json: String) = Count(json.toLong())
    }
}
data class Ratio(val value: Double) {
    public fun toJson() = klaxon.toJsonString(value)

    companion object {
        public fun fromJson(json: String) = Ratio(json.toDouble())
    }
}
data class Title(val value: String) {
    public fun toJson() = klaxon.toJsonString(value)

    companion object {
        public fun fromJson(json: String) = Title(klaxon.parseArray<String>("[${json}]")!![0])
    }
}
data class Flag(val value: Boolean) {
    public fun toJson() = klaxon.toJsonString(value)

    companion object {
        public fun fromJson(json: String) = Flag(klaxon.parseArray<Boolean>("[${json}]")!![0])
    }
}
data class When(val value: OffsetDateTime) {
    public fun toJson() = klaxon.toJsonString(value)

    companion object {
        public fun fromJson(json: String) = When(klaxon.parseArray<OffsetDateTime>("[${json}]")!![0])
    }
}

enum class Color(val value: String) {
    Red("red"),
    Green("green"),
    LightBlue("light blue");

    public fun toJson() = klaxon.toJsonString(value)

    companion object {
        public fun fromJson(json: String) = fromValue(klaxon.parseArray<String>("[${json}]")!![0])

        public fun fromValue(value: String): Color = when (value) {
            "red"        -> Red
            "green"      -> Green
            "light blue" -> LightBlue
            else         -> throw IllegalArgumentException()
        }
    }
}

sealed class Either {
    class DoubleArrayValue(val value: List<Double>) : Either()
    class IntegerValue(val value: Long)             : Either()
    class StringValue(val value: String)            : Either()
    class NullValue()                               : Either()

    public fun toJson(): String = klaxon.toJsonString(when (this) {
        is DoubleArrayValue -> this.value
        is IntegerValue     -> this.value
        is StringValue      -> this.value
        is NullValue        -> "null"
    })

    companion object {
        public fun fromJson(json: String): Either = fromJson(JsonValue(Parser().parse(StringBuilder(json)), null, null, klaxon))

        public fun fromJson(jv: JsonValue): Either = when (jv.inside) {
            is JsonArray<*> -> DoubleArrayValue(jv.array?.let { klaxon.parseFromJsonArray<Double>(it) }!!)
            is Int, is Long -> IntegerValue((jv.int?.toLong() ?: jv.longValue)!!)
            is String       -> StringValue(jv.string!!)
            null            -> NullValue()
            else            -> throw IllegalArgumentException()
        }
    }
}

data class Point (
    val x: Double
) {
    public fun toJson() = klaxon.toJsonString(this)

    companion object {
        public fun fromJson(json: String) = klaxon.parse<Point>(json)
    }
}

