@file:UseSerializers(OffsetDateTimeSerializer::class)

package quicktype

import java.time.OffsetDateTime

import kotlinx.serialization.*
import kotlinx.serialization.json.*
import kotlinx.serialization.descriptors.*
import kotlinx.serialization.encoding.*

typealias Ints = List<Long>
typealias Names = List<String>
typealias Table = HashMap<String, Double>
typealias Bag = JsonObject
typealias Count = Long
typealias Ratio = Double
typealias Title = String
typealias Flag = Boolean
typealias When = OffsetDateTime

@Serializable
enum class Color(val value: String) {
    @SerialName("red") Red("red"),
    @SerialName("green") Green("green"),
    @SerialName("light blue") LightBlue("light blue");
}

typealias Either = JsonElement

@Serializable
data class Point (
    val x: Double
)

object OffsetDateTimeSerializer : KSerializer<OffsetDateTime> {
    override val descriptor: SerialDescriptor = PrimitiveSerialDescriptor("OffsetDateTime", PrimitiveKind.STRING)
    override fun deserialize(decoder: Decoder): OffsetDateTime = OffsetDateTime.parse(decoder.decodeString())
    override fun serialize(encoder: Encoder, value: OffsetDateTime) {
        encoder.encodeString(java.time.format.DateTimeFormatter.ISO_OFFSET_DATE_TIME.format(value))
    }
}

